import { log } from 'console';
import VideoPlayer from '../../components/VideoPlayer/page.jsx';


async function getVideoData() {
  // Aqui você busca as URLs da sua API
  const res = await fetch('http://localhost:4000/api/v2/hianime/episode/sources?animeEpisodeId=my-hero-academia-322?ep=6212');
  const data = await res.json();

  console.log(data);
  
  return {
    videoUrl: data.sources,     // exemplo: https://cdn.site.com/video/playlist.m3u8
    subtitleUrl:data.tracks ,   // exemplo: https://cdn.site.com/subs/legenda.vtt
  };
}

export default async function Page() {
  const { videoUrl, subtitleUrl } = await getVideoData();
  console.log({ videoUrl, subtitleUrl });
  return (
    <main className="flex justify-center items-center min-h-screen bg-black">
      <VideoPlayer src={videoUrl} subtitles={subtitleUrl} />
    </main>
  );
}
